package run.halo.starter;
import java.util.Map;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.springframework.test.web.reactive.server.WebTestClient;
import reactor.core.publisher.Mono;
import static org.mockito.Mockito.*;
class McpEndpointTest {
 private McpSettings settings(){var s=new McpSettings();s.setEnabled(true);s.setAllowedOrigin("https://blog.example");return s;}
 @Test void realJsonRpcLifecycleAndToolsAreSupported(){var config=mock(McpConfigService.class);var tools=mock(BlogMcpTools.class);when(config.settings()).thenReturn(Mono.just(settings()));when(config.validMcpToken(any())).thenReturn(Mono.just(true));when(tools.list()).thenReturn(List.of(Map.of("name","site_info")));when(tools.call(eq("site_info"),any())).thenReturn(Mono.just(Map.of("siteName","本站")));var api=WebTestClient.bindToRouterFunction(new McpEndpoint(config,new McpAccess(),new OwnerSessions(),tools).endpoint()).build();
 api.post().uri("/mcp").header("X-Frame-MCP-Token","token").bodyValue(Map.of("jsonrpc","2.0","id",1,"method","initialize","params",Map.of("protocolVersion","2025-11-25"))).exchange().expectStatus().isOk().expectBody().jsonPath("$.result.protocolVersion").isEqualTo("2025-11-25");
 api.post().uri("/mcp").header("X-Frame-MCP-Token","token").header("MCP-Protocol-Version","2025-11-25").bodyValue(Map.of("jsonrpc","2.0","method","notifications/initialized")).exchange().expectStatus().isAccepted().expectBody().isEmpty();
 api.post().uri("/mcp").header("X-Frame-MCP-Token","token").header("MCP-Protocol-Version","2025-11-25").bodyValue(Map.of("jsonrpc","2.0","id","tools","method","tools/list")).exchange().expectStatus().isOk().expectBody().jsonPath("$.result.tools[0].name").isEqualTo("site_info");
 api.post().uri("/mcp").header("X-Frame-MCP-Token","token").header("MCP-Protocol-Version","2025-11-25").bodyValue(Map.of("jsonrpc","2.0","id",3,"method","tools/call","params",Map.of("name","site_info","arguments",Map.of()))).exchange().expectStatus().isOk().expectBody().jsonPath("$.result.structuredContent.siteName").isEqualTo("本站").jsonPath("$.result.isError").isEqualTo(false);
 api.get().uri("/mcp").header("X-Frame-MCP-Token","token").exchange().expectStatus().isEqualTo(405).expectHeader().valueEquals("Allow","POST");}
 @Test void unknownOrWriteToolIsAnErrorAndNeverExecutesAnotherAction(){var config=mock(McpConfigService.class);var tools=mock(BlogMcpTools.class);when(config.settings()).thenReturn(Mono.just(settings()));when(config.validMcpToken(any())).thenReturn(Mono.just(true));when(tools.call(eq("delete_moment"),any())).thenReturn(Mono.error(new IllegalArgumentException("未知或未开放的工具")));var api=WebTestClient.bindToRouterFunction(new McpEndpoint(config,new McpAccess(),new OwnerSessions(),tools).endpoint()).build();api.post().uri("/mcp").header("X-Frame-MCP-Token","token").header("MCP-Protocol-Version","2025-11-25").bodyValue(Map.of("jsonrpc","2.0","id",1,"method","tools/call","params",Map.of("name","delete_moment","arguments",Map.of()))).exchange().expectBody().jsonPath("$.result.isError").isEqualTo(true);}
 @Test void originAndAuthenticationAreAlwaysChecked(){var config=mock(McpConfigService.class);var tools=mock(BlogMcpTools.class);when(config.settings()).thenReturn(Mono.just(settings()));when(config.validMcpToken(any())).thenReturn(Mono.just(false));var api=WebTestClient.bindToRouterFunction(new McpEndpoint(config,new McpAccess(),new OwnerSessions(),tools).endpoint()).build();api.post().uri("/mcp").header("Origin","https://evil.example").bodyValue("{}").exchange().expectStatus().isForbidden();api.post().uri("/mcp").bodyValue("{}").exchange().expectStatus().isUnauthorized();verifyNoInteractions(tools);}
 @Test void disabledServiceAndInvalidProtocolCannotCallTools(){var config=mock(McpConfigService.class);var tools=mock(BlogMcpTools.class);var s=settings();s.setEnabled(false);when(config.settings()).thenReturn(Mono.just(s));var api=WebTestClient.bindToRouterFunction(new McpEndpoint(config,new McpAccess(),new OwnerSessions(),tools).endpoint()).build();api.post().uri("/mcp").bodyValue("{}").exchange().expectStatus().isEqualTo(503);s.setEnabled(true);when(config.validMcpToken(any())).thenReturn(Mono.just(true));api.post().uri("/mcp").header("X-Frame-MCP-Token","token").bodyValue(Map.of("jsonrpc","2.0","id",1,"method","tools/list")).exchange().expectStatus().isBadRequest();verifyNoInteractions(tools);}
}
